window.addEventListener('message', (event) => {
    if (event.source !== window) {
        return;
    }

    if (event.data.type === 'BDTLL_TIMESTAMP_REQUEST') {
        const elementId = event.data.elementId;
        const element = document.querySelector('[data-bdtll-timestamp-id="' + elementId + '"]');

        if (!element) {
            window.postMessage({
                type: 'BDTLL_TIMESTAMP_RESPONSE',
                elementId: elementId,
                timestamp: Date.now(),
                error: "ReactPropsExtractor: no element found for id " + elementId,
                errorCode: 1
            }, '*');
            return;
        }

        try {
            const reactPropsKey = Object.getOwnPropertyNames(element).find(key => key.startsWith('__reactProps'));

            if (reactPropsKey !== undefined) {
                const props = element[reactPropsKey];
                const timestampMs = props.children.props.children[0].props.message.timestampMs; // looks like [408, 4019544377, _tag: 'i64']

                if (timestampMs && Array.isArray(timestampMs) && timestampMs.length >= 2) {
                    const first32BitsValue = timestampMs[0];
                    const last32BitsValue = timestampMs[1];
                    const timestamp = (first32BitsValue * Math.pow(2, 32)) + last32BitsValue;

                    window.postMessage({
                        type: 'BDTLL_TIMESTAMP_RESPONSE',
                        elementId: elementId,
                        timestamp: timestamp
                    }, '*');

                    return;
                }
            }

            window.postMessage({
                type: 'BDTLL_TIMESTAMP_RESPONSE',
                elementId: elementId,
                timestamp: Date.now(),
                error: "ReactPropsExtractor: no timestampMs found for id " + elementId,
                errorCode: 2
            }, '*');

        } catch (error) {
            window.postMessage({
                type: 'BDTLL_TIMESTAMP_RESPONSE',
                elementId: elementId,
                timestamp: Date.now(),
                error: "ReactPropsExtractor: " + error.message + " for id " + elementId,
                errorCode: 3
            }, '*');
        }
    }
});